/bin/bash -lc "node - <<'NODE'
const base='http://localhost:8080';
let token=null, requests=0;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function refresh(){
  for(;;){
    const r=await fetch(base+'/token',{method:'POST'});
    if(r.status===429){const s=Number(r.headers.get('retry-after')||1); console.error('token throttle',s); await sleep(s*1000); continue;}
    if("'!r.ok) throw new Error('"'token '+r.status);
    token=(await r.json()).token; console.error('new token'); return;
  }
}
async function api(path){
  for(;;){
    if("'!token) await refresh();
    const r=await fetch(base+path,{headers:{Authorization:'"'Bearer '+token}}); requests++;
    if(r.status===401){console.error('expired token'); token=null; continue;}
    if(r.status===429){const s=Number(r.headers.get('retry-after')||1); console.error('throttle',s,path); await sleep(s*1000); continue;}
    if("'!r.ok) throw new Error(path+'"' '+r.status+' '+await r.text());
    return r.json();
  }
}
const unique=new Map(); let duplicates=0, page=1, pages;
while(true){
  const data=await api('/orders?page='+page); pages=data.total_pages;
  for(const o of data.items){if(unique.has(o.id)) duplicates++; else unique.set(o.id,o);}
  console.error('orders page',page,'of',pages);
  if("'!data.next) break;
  const m=data.next.match(/[?&]page=('"\\d+)/); if("'!m) throw new Error('"'bad next '+data.next); page=Number(m[1]);
}
const start=Date.parse('2025-03-01T00:00:00.000Z'), end=Date.parse('2025-06-01T00:00:00.000Z');
const qualifying=[...unique.values()].filter(o=>o.status==='shipped' && Date.parse(o.placed_at)>=start && Date.parse(o.placed_at)<end);
const customers=new Map();
for(const o of qualifying) if("'!customers.has(o.customer_id)) customers.set(o.customer_id,await api('"'/customers/'+encodeURIComponent(o.customer_id)));
const totals={north:0,south:0,east:0,west:0};
for(const o of qualifying){const c=customers.get(o.customer_id); const cents=Math.floor((o.amount_cents*(100-c.discount_pct)+50)/100); totals[c.region]+=cents;}
const result={total_cents:Object.values(totals).reduce((a,b)=>a+b,0),order_count:qualifying.length,duplicates_skipped:duplicates,by_region:totals};
console.log(JSON.stringify(result)); console.error({pages,listed:unique.size,duplicates,qualifying:qualifying.length,customers:customers.size,requests});
NODE"

